// План specs/addresses.md 1.1 (кейс AD-01). Admin, компания «test». Форму не сохраняем. Зависит от Google Places.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, addressInput, openNewJobAddressDetails, setEnglish, typeAndPickSuggestion, unitInput } from './address-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: номер квартиры → Unit/Apt (#8ffd6e26)', () => {
  test('New Job: "Apt 5B" typed in the address moves to Unit/Apt and the address keeps only the street #8ffd6e26 @desktop @prod-safe @google-places', async ({ page }) => {
    await setEnglish(page);
    await openNewJobAddressDetails(page);

    await typeAndPickSuggestion(page, '2221 NW Federal Hwy Apt 5B', '2221 NW Federal Hwy apt 5b', 'Stuart, FL, USA');

    await expect(unitInput(page)).toHaveValue('Apt 5B');
    // ZIP приходит ~1 с после выбора — ждём значение, а не время.
    await expect(page.getByLabel('ZIP Code', { exact: true })).toHaveValue('34994');
    await expect(addressInput(page)).toHaveValue('2221 NW Federal Hwy, Stuart, FL 34994, USA');
    await expect(addressInput(page)).not.toHaveValue(/apt\s*5b/i);
    await expect(page.getByLabel('City', { exact: true })).toHaveValue('Stuart');
    await expect(page.getByLabel('Region/State', { exact: true })).toHaveValue('Florida');
  });
});
